	// scheme + existing port
	addr, err = ParseHostPortAddr("https://localhost", 443)
	c.Assert(err, IsNil)
	c.Assert(addr.AddrNetwork, Equals, "https")
	c.Assert(addr.Addr, Equals, "localhost:443")

	// success
